#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto do_op = [&](int x, int y){
        // x>=1, y>=1, x+y<n
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    // Place elements from left, one at a time
    for(int placed=0; placed<n-1; placed++){
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        int rem = n - placed;

        // Move p[pos] to position placed.
        // Step 1: bring target to position n-1
        if(pos != n-1){
            // op(x=pos+1, y=n-1-pos): new = p[pos+1..n-1] + p[pos+1..pos]... wait
            // Actually: y = n-1-pos, x = pos+1, x+y = n, invalid.
            // op(x=pos+1, y=n-2-pos) if n-2-pos>=1 i.e. pos<=n-3
            // new = p[pos+2..n-1] + p[pos+1] + p[0..pos]
            // target was at pos, now at end: p[0..pos] starts at position (n-2-pos)+(1)= n-1-pos
            // target at new position n-1. Yes!
            if(pos <= n-3){
                do_op(pos+1, n-2-pos);
            } else {
                // pos = n-2, target at second-to-last
                // op(1,1): new = p[n-1], p[1..n-2], p[0]. Target at n-2 goes to n-2 still? 
                // new[0]=p[n-1], new[1..n-2]=p[1..n-2], new[n-1]=p[0]
                // target was at n-2, in new it's at n-2. Hmm.
                // op(x=n-2, y=1): new = p[n-1], p[0..n-2]. target at n-2 -> position n-1
                if(n-2+1 < n){ // n-1 < n, true
                    do_op(n-2, 1);
                }
            }
        }
        // Now target at n-1
        // Step 2: move from n-1 to placed
        // op(x=1, y=placed+1): x+y=placed+2, need placed+2<n => placed<n-2
        if(placed < n-2){
            do_op(1, placed+1);
        } else {
            // placed=n-2, target at n-1 already, only 2 left, must be in order
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
